//! Tests for the TLS certificate validation behavior of the client.
//!
//! These tests used to hit badssl.com over the network, which made them flaky
//! whenever badssl.com was slow or unreachable from CI. They now run against
//! local TLS servers using the certificates generated by
//! `tests/assets/generate-certs.bash`.
//!
//! Like `test_proxy`, this test is disabled when the ring rustls features are
//! enabled: combined with the default rustls features, they prevent rustls from
//! selecting a process-level crypto provider, which breaks the test servers.
#![cfg(not(any(feature = "tls-rustls-webpki-roots-ring", feature = "tls-rustls-native-roots-ring")))]

mod tools;

use std::time::Duration;

use attohttpc::ErrorKind;

/// Every request gets an explicit timeout so that an unexpected hang fails the
/// test with a clear error instead of blocking the CI job.
const REQUEST_TIMEOUT: Duration = Duration::from_secs(15);

fn ca_certificate() -> attohttpc::Certificate {
    attohttpc::Certificate::from_pem(include_bytes!("assets/ca.pem")).unwrap()
}

#[tokio::test(flavor = "multi_thread")]
async fn test_error_when_self_signed() -> Result<(), anyhow::Error> {
    let port = tools::start_hello_world_server(true).await?;

    let err = attohttpc::get(format!("https://localhost:{port}"))
        .timeout(REQUEST_TIMEOUT)
        .send()
        .err()
        .expect("request should have failed");
    println!("{err:?}");

    match err.kind() {
        ErrorKind::Tls(_) => (),
        _ => panic!("wrong error returned: {err:?}"),
    }

    Ok(())
}

#[tokio::test(flavor = "multi_thread")]
async fn test_accept_invalid_certs_ok_when_self_signed() -> Result<(), anyhow::Error> {
    let port = tools::start_hello_world_server(true).await?;

    let resp = attohttpc::get(format!("https://localhost:{port}"))
        .danger_accept_invalid_certs(true)
        .timeout(REQUEST_TIMEOUT)
        .send()
        .expect("request should have succeeded");
    assert_eq!(resp.text().unwrap(), "hello");

    Ok(())
}

#[tokio::test(flavor = "multi_thread")]
async fn test_accept_invalid_certs_ok_when_wrong_host() -> Result<(), anyhow::Error> {
    let port = tools::start_wrong_host_server().await?;

    let resp = attohttpc::get(format!("https://localhost:{port}"))
        .danger_accept_invalid_certs(true)
        .timeout(REQUEST_TIMEOUT)
        .send()
        .expect("request should have succeeded");
    assert_eq!(resp.text().unwrap(), "hello");

    Ok(())
}

#[tokio::test(flavor = "multi_thread")]
async fn test_error_when_wrong_host() -> Result<(), anyhow::Error> {
    let port = tools::start_wrong_host_server().await?;

    // The test CA is added as a trusted root so that the only problem with the
    // certificate is the hostname mismatch, like `wrong.host.badssl.com`.
    let err = attohttpc::get(format!("https://localhost:{port}"))
        .add_root_certificate(ca_certificate())
        .timeout(REQUEST_TIMEOUT)
        .send()
        .err()
        .expect("request should have failed");

    match err.kind() {
        ErrorKind::Tls(_) => (),
        _ => panic!("wrong error returned: {err:?}"),
    }

    Ok(())
}

